// #370's consumer is generated by the installed candidate tool and uses the
// same tarballs and isolated Go proxy as the getting-started smoke.
import assert from "node:assert/strict";
import { cpSync, existsSync, mkdirSync, readFileSync, readdirSync, realpathSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

export function holdGenericComposition({ root, consumer: probe, go, pnpm, run, step }) {
  // A separate declaration world keeps the getting-started family's names
  // out of generic family-draw validation. This is still the same candidate
  // install: its manifests and tarballs are copied from the packed probe.
  const consumer = join(dirname(probe), "generic-consumer");
  mkdirSync(consumer, { recursive: true });
  for (const name of ["go.mod", "go.sum", "package.json", "pnpm-workspace.yaml", "tarballs"]) {
    cpSync(join(probe, name), join(consumer, name), { recursive: true });
  }
  const corpus = join(root, "conformance", "corpora", "generic-composition");
  cpSync(join(corpus, "api", "contracts"), join(consumer, "api", "contracts"), { recursive: true });
  cpSync(join(corpus, "smoke", "live"), join(consumer, "generic-smoke"), { recursive: true });
  cpSync(join(corpus, "smoke", "data"), join(consumer, "generic-data-smoke"), { recursive: true });
  step("installed generator: closed Function and two-provider live Holder composition");
  run("go", ["tool", "nightseam", "generate"], { cwd: consumer, env: go, stdio: ["ignore", "inherit", "inherit"] });

  const file = join(consumer, "package.json");
  const manifest = JSON.parse(readFileSync(file, "utf8"));
  manifest.name = "generic-composition-smoke";
  for (const name of Object.keys(manifest.dependencies)) {
    if (!name.startsWith("@nightseam/")) delete manifest.dependencies[name];
  }
  for (const directory of readdirSync(join(consumer, "api", "ts"))) {
    const generated = JSON.parse(readFileSync(join(consumer, "api", "ts", directory, "package.json"), "utf8"));
    // These are the consumer's own generated packages. Only the published
    // Nightseam dependencies resolve to candidate tarballs.
    manifest.dependencies[generated.name] = `link:./api/ts/${directory}`;
  }
  writeFileSync(file, JSON.stringify(manifest, null, 2) + "\n");
  pnpm(["install", "--no-frozen-lockfile"], { cwd: consumer, stdio: ["ignore", "inherit", "inherit"] });
  for (const component of ["duplex", "runtime", "live"]) {
    assert(realpathSync(join(consumer, "node_modules", "@nightseam", component)).startsWith(realpathSync(consumer)), `${component}: installed runtime resolved outside the packed consumer`);
  }
  const compilerOptions = { target: "ES2022", module: "NodeNext", moduleResolution: "NodeNext", strict: true, skipLibCheck: false, noEmit: true, allowImportingTsExtensions: true, types: ["node"] };
  writeFileSync(join(consumer, "generic-smoke", "tsconfig.json"), JSON.stringify({ compilerOptions, include: ["*.ts"] }, null, 2) + "\n");
  step("checking the generated generic consumer against installed declarations");
  pnpm(["exec", "tsc", "-p", "generic-smoke/tsconfig.json"], { cwd: consumer, stdio: ["ignore", "inherit", "inherit"] });

  // The data-only instantiation has its own source and import closure. Live
  // packages installed elsewhere in the smoke cannot hide an accidental edge.
  const pending = ["@probe/compose-cell-binding"];
  const visited = new Set();
  const allowed = new Set(["@probe/compose-cell-binding", "@probe/compose-cell-client", "@nightseam/runtime", "@nightseam/duplex"]);
  while (pending.length) {
    const name = pending.pop();
    if (visited.has(name)) continue;
    visited.add(name);
    assert(allowed.has(name), `scalar generic TypeScript dependency closure reached ${name}`);
    const installed = JSON.parse(readFileSync(join(consumer, "node_modules", name, "package.json"), "utf8"));
    pending.push(...Object.keys(installed.dependencies ?? {}));
  }
  assert.deepEqual(visited, allowed, "scalar generic dependency closure omitted a required package");
  for (const name of ["compose-cell-client", "compose-cell-binding"]) {
    const directory = join(consumer, "api", "ts", name);
    const generated = JSON.parse(readFileSync(join(directory, "package.json"), "utf8"));
    assert.deepEqual(Object.keys(generated.dependencies).filter(name => name !== "@nightseam/duplex" && name !== "@nightseam/runtime" && name !== "@probe/compose-cell-client"), [], `${name}: data-only generic gained a provider or live dependency`);
    for (const file of readdirSync(join(directory, "src"))) {
      assert.doesNotMatch(readFileSync(join(directory, "src", file), "utf8"), /@nightseam\/live|@probe\/(?:functions|numbers|texts|holder)-/, `${name}/${file}: data-only generic imported live conversion`);
    }
  }
  const closure = run("go", ["list", "-deps", "./generic-data-smoke"], { cwd: consumer, env: go });
  assert.doesNotMatch(closure, /github\.com\/Bitspark\/nightseam\/live\/go|example\.com\/probe\/api\/go\/(?:functions|numbers|texts|holder)-/, "scalar generic Go import closure reached live conversion");
  const resolved = JSON.parse(run("go", ["list", "-m", "-json", "github.com/Bitspark/nightseam"], { cwd: consumer, env: go }));
  assert.equal(resolved.Replace, undefined, "generic consumer resolved through a Go replace");
  assert(resolved.Dir.startsWith(go.GOMODCACHE), "generic consumer resolved outside its isolated Go module cache");

  // Install the scalar TypeScript consumer separately, with no live package
  // available through a parent node_modules directory or another fixture.
  const dataConsumer = join(dirname(probe), "generic-data-consumer");
  mkdirSync(dataConsumer, { recursive: true });
  for (const name of ["pnpm-workspace.yaml", "tarballs", "generic-data-smoke", "api/ts/compose-cell-client", "api/ts/compose-cell-binding"]) {
    cpSync(join(consumer, name), join(dataConsumer, name), { recursive: true });
  }
  const dataManifest = { name: "generic-data-smoke", private: true, type: "module", devDependencies: manifest.devDependencies, dependencies: Object.fromEntries(Object.entries(manifest.dependencies).filter(([name]) => allowed.has(name))) };
  writeFileSync(join(dataConsumer, "package.json"), JSON.stringify(dataManifest, null, 2) + "\n");
  writeFileSync(join(dataConsumer, "tsconfig.json"), JSON.stringify({ compilerOptions, include: ["generic-data-smoke/*.ts"] }, null, 2) + "\n");
  pnpm(["install", "--no-frozen-lockfile"], { cwd: dataConsumer, stdio: ["ignore", "inherit", "inherit"] });
  assert.equal(existsSync(join(dataConsumer, "node_modules", "@nightseam", "live")), false, "scalar TypeScript install unexpectedly contains live");
  pnpm(["exec", "tsc", "-p", "tsconfig.json"], { cwd: dataConsumer, stdio: ["ignore", "inherit", "inherit"] });
  step("running scalar Cell without a live environment in Go and TypeScript");
  run("go", ["run", "./generic-data-smoke"], { cwd: consumer, env: go, stdio: ["ignore", "inherit", "inherit"] });
  run("node", ["--experimental-strip-types", "--disable-warning=ExperimentalWarning", "generic-data-smoke/main.ts"], { cwd: dataConsumer, stdio: ["ignore", "inherit", "inherit"] });
  step("real socket: Go generated Cell serves Function and both Holder providers to the installed TypeScript consumer");
  run("go", ["test", "-count=1", "-v", "./generic-smoke"], { cwd: consumer, env: go, stdio: ["ignore", "inherit", "inherit"] });
  step("generic candidate consumer passed: closed callable, two associated live draws, retained values, release, and scalar dependency isolation");
}
